import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Link, NavLink, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import wsService from '../services/wsService';
import './Navbar.css';

/* Level colours — Newcomer grey, Thinker blue, Innovator green, Visionary purple, Legend gold */
const LEVEL_COLORS = {
  Newcomer:  '#94a3b8',
  Thinker:   '#06b6d4',
  Innovator: '#10b981',
  Visionary: '#7c3aed',
  Legend:    '#d4a853',
};

const LEVEL_ORDER = ['Newcomer', 'Thinker', 'Innovator', 'Visionary', 'Legend'];

function xpProgressForNavbar(xp, level) {
  const idx = LEVEL_ORDER.indexOf(level);
  if (idx < 0) return 0;
  if (level === 'Legend') return 100;
  const curMin = [0, 200, 500, 1000, 2500][idx];
  const nextMin = [200, 500, 1000, 2500, Infinity][idx];
  if (nextMin === Infinity) return 100;
  const raw = ((xp - curMin) / (nextMin - curMin)) * 100;
  return Math.min(100, Math.max(0, Math.round(raw)));
}

/* ── NotificationBell ── */
function NotificationBell({ userId }) {
  const [notifications, setNotifications] = useState([]);
  const [unread, setUnread] = useState(0);
  const [open, setOpen] = useState(false);
  const dropdownRef = useRef(null);
  const subRef = useRef(null);
  const openRef = useRef(false);

  useEffect(() => {
    openRef.current = open;
  }, [open]);

  /* Mark all read when dropdown opens */
  useEffect(() => {
    if (!open) return;
    setUnread(0);
    setNotifications((prev) => prev.map((n) => ({ ...n, read: true })));
  }, [open]);

  /* WS subscription */
  useEffect(() => {
    if (!userId) return;
    wsService.subscribe(`/topic/user/${userId}/notifications`, (payload) => {
      const alreadyViewing = openRef.current;
      const note = {
        id: payload.id ?? `n-${Date.now()}-${Math.random().toString(36).slice(2, 9)}`,
        type: payload.type || 'INFO',
        message: payload.message || 'New notification',
        time: new Date(),
        read: alreadyViewing,
      };
      setNotifications((prev) => [note, ...prev].slice(0, 20));
      if (!alreadyViewing) {
        setUnread((n) => n + 1);
      }
    }).then((sub) => {
      subRef.current = sub;
    });
    return () => wsService.unsubscribe(subRef.current);
  }, [userId]);

  /* Close on outside click */
  useEffect(() => {
    const handler = (e) => {
      if (dropdownRef.current && !dropdownRef.current.contains(e.target)) {
        setOpen(false);
      }
    };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, []);

  const toggleDropdown = useCallback(() => {
    setOpen((o) => !o);
  }, []);

  const typeIcon = (type) => {
    if (type === 'COLLAB_REQUEST') return '🤝';
    if (type === 'PLAGIARISM_REPORT') return '🚨';
    if (type === 'COLLAB_ACCEPTED') return '✅';
    return '🔔';
  };

  return (
    <div className="nb-wrap" ref={dropdownRef}>
      <button
        id="notification-bell-btn"
        type="button"
        className="nb-bell"
        onClick={toggleDropdown}
        aria-expanded={open}
        aria-label={unread ? `${unread} unread notifications` : 'Notifications'}
        title="Notifications"
      >
        <svg className="nb-bell-svg" viewBox="0 0 24 24" aria-hidden="true">
          <path
            fill="currentColor"
            d="M12 22a2.5 2.5 0 0 0 2.45-2h-4.9A2.5 2.5 0 0 0 12 22zm8-5V11a8 8 0 1 0-16 0v6l-2 2V20h20v-2l-2-2z"
          />
        </svg>
        {unread > 0 && (
          <span className="nb-badge">{unread > 9 ? '9+' : unread}</span>
        )}
      </button>

      {open && (
        <div className="nb-dropdown fade-in" role="menu">
          <div className="nb-dropdown__header">
            <span className="nb-dropdown__title">Notifications</span>
            <button type="button" className="nb-clear-btn" onClick={() => setNotifications([])}>
              Clear all
            </button>
          </div>

          <div className="nb-dropdown__list">
            {notifications.length === 0 ? (
              <div className="nb-empty">
                <span>🔕</span>
                <p>No notifications yet</p>
              </div>
            ) : (
              notifications.map((n) => (
                <div key={n.id} className={`nb-item ${n.read ? 'nb-item--read' : 'nb-item--unread'}`}>
                  <span className="nb-item__icon">{typeIcon(n.type)}</span>
                  <div className="nb-item__body">
                    <p className="nb-item__msg">{n.message}</p>
                    <span className="nb-item__time">
                      {n.time.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                    </span>
                  </div>
                </div>
              ))
            )}
          </div>
        </div>
      )}
    </div>
  );
}

/* ================================================================
   Navbar
   ================================================================ */
export default function Navbar() {
  const { currentUser, logout, isAdmin } = useAuth();
  const navigate = useNavigate();
  const [menuOpen, setMenuOpen] = useState(false);

  const navLinks = [
    { to: '/',                label: '💡 Feed' },
    { to: '/battle',          label: '⚔️ Battle' },
    { to: '/leaderboard',     label: '🏆 Leaderboard' },
    { to: '/hall-of-fame',    label: '🌟 Hall of Fame' },
    { to: '/collab-requests', label: '🤝 Collabs' },
    ...(isAdmin ? [{ to: '/admin', label: '🛡️ Admin' }] : []),
  ];

  return (
    <nav className="navbar">
      <div className="navbar-inner">
        {/* Logo */}
        <Link to="/" className="navbar-logo">
          <span className="navbar-logo-icon">⚡</span>
          <span className="navbar-logo-text">
            Idea<span className="gradient-text">Forge</span>
          </span>
        </Link>

        {/* Desktop nav links */}
        <ul className="navbar-links">
          {navLinks.map(({ to, label }) => (
            <li key={to}>
              <NavLink
                to={to}
                end={to === '/'}
                className={({ isActive }) =>
                  `navbar-link ${isActive ? 'navbar-link--active' : ''}`
                }
              >
                {label}
              </NavLink>
            </li>
          ))}
        </ul>

        {/* Right side — notification bell + user chip */}
        {currentUser && (
          <div className="navbar-user">
            {/* Notification bell */}
            <NotificationBell userId={currentUser.id} />

            {/* XP / level chip */}
            <div
              className="navbar-level-chip"
              style={{ '--level-color': LEVEL_COLORS[currentUser.level] || '#7c3aed' }}
            >
              <span className="navbar-level-badge">{currentUser.level}</span>
              <div className="navbar-xp-bar">
                <div
                  className="navbar-xp-fill"
                  style={{ width: `${xpProgressForNavbar(currentUser.xp, currentUser.level)}%` }}
                />
              </div>
              <span className="navbar-xp-label">{currentUser.xp} XP</span>
            </div>

            {/* Avatar / profile link */}
            <button
              className="navbar-avatar"
              onClick={() => navigate('/profile')}
              title="My Profile"
            >
              {currentUser.name?.charAt(0).toUpperCase() || '?'}
            </button>

            <button className="btn-secondary navbar-logout" onClick={logout}>
              Logout
            </button>
          </div>
        )}

        {/* Hamburger */}
        <button
          className={`navbar-hamburger ${menuOpen ? 'open' : ''}`}
          onClick={() => setMenuOpen((o) => !o)}
          aria-label="Toggle menu"
        >
          <span /><span /><span />
        </button>
      </div>

      {/* Mobile drawer */}
      {menuOpen && (
        <div className="navbar-drawer">
          {navLinks.map(({ to, label }) => (
            <NavLink
              key={to}
              to={to}
              end={to === '/'}
              className="navbar-drawer-link"
              onClick={() => setMenuOpen(false)}
            >
              {label}
            </NavLink>
          ))}
          {currentUser && (
            <button className="btn-danger" onClick={logout} style={{ margin: '8px 16px' }}>
              Logout
            </button>
          )}
        </div>
      )}
    </nav>
  );
}
